import { z } from 'zod';
import raw from '@data/acid_base_kntt.json';
import {
  loadDataset,
  LocalizedTextSchema,
  ReviewStatusSchema,
  type Source,
} from '@/core/data/dataset';

/**
 * Hóa học 11 KNTT Bài 2 "Cân bằng trong dung dịch nước" (data/acid_base_kntt.json, generated by
 * scripts/data/gen_acid_base_kntt.py; every value from the textbook, review_status pending,
 * DATA_REVIEW HH11-AB-1): the ion product of water Kw = 10⁻¹⁴ at 25 °C (tr. 20), pH = −lg[H⁺]
 * (tr. 21), the colours of litmus and phenolphthalein (Bảng 2.1, tr. 23), the pH of everyday
 * solutions (Hình 2.1) and of body fluids, water and soils (Hình 2.4, tr. 22).
 */
const EverydaySchema = z.object({
  id: z.string().min(1),
  name: LocalizedTextSchema,
  pH: z.number().min(0).max(14),
  book: z.string().min(1),
  review_status: ReviewStatusSchema,
});
const RangeSchema = z.object({
  id: z.string().min(1),
  name: LocalizedTextSchema,
  low: z.number().min(0).max(14),
  high: z.number().min(0).max(14),
  book: z.string().min(1),
  review_status: ReviewStatusSchema,
});
const ExtraSchema = z.object({
  kw: z.object({ value: z.number().positive(), temperature_C: z.number(), book: z.string() }),
  indicators: z.object({
    litmus: z.object({
      red_max: z.number(),
      violet: z.number(),
      blue_min: z.number(),
      colours: z.object({ red: z.string(), violet: z.string(), blue: z.string() }),
    }),
    phenolphthalein: z.object({
      colourless_below: z.number(),
      pink_above: z.number(),
      colours: z.object({ colourless: z.string(), pink: z.string() }),
    }),
    ph_paper: z.object({ colours: z.array(z.string()).length(14) }),
  }),
  ranges: z.array(RangeSchema).min(1),
});

const dataset = loadDataset('acid_base_kntt', EverydaySchema, raw);
const extra = ExtraSchema.parse(raw);

export type Everyday = z.infer<typeof EverydaySchema>;
export type PhRange = z.infer<typeof RangeSchema>;

export const EVERYDAY: readonly Everyday[] = dataset.items;
export const PH_RANGES: readonly PhRange[] = extra.ranges;
/** Kw at 25 °C as the textbook gives it (tr. 20). */
export const KW = extra.kw.value;
export const LITMUS = extra.indicators.litmus;
export const PHENOLPHTHALEIN = extra.indicators.phenolphthalein;
/** Screen colours of pH paper at pH 1 … 14 (illustrative, after Bảng 2.1). */
export const PH_PAPER: readonly string[] = extra.indicators.ph_paper.colours;
export const AQUEOUS_SOURCE: Source = dataset.source;

/** pH = −lg[H⁺] (tr. 21). */
export const phOf = (h: number) => -Math.log10(h);
/** [H⁺] = 10^−pH (tr. 21). */
export const hOf = (pH: number) => 10 ** -pH;
/** [OH⁻] = Kw/[H⁺]. */
export const ohOf = (h: number) => KW / h;

export type Medium = 'acid' | 'neutral' | 'base';

/** pH < 7 acid, = 7 neutral, > 7 base (tr. 21); "= 7" within round-off of the input. */
export function mediumOf(pH: number): Medium {
  if (Math.abs(pH - 7) <= 1e-9) return 'neutral';
  return pH < 7 ? 'acid' : 'base';
}

export type LitmusColour = 'red' | 'violet' | 'blue' | 'between';

/** Bảng 2.1: red at pH ≤ 6, violet at pH = 7, blue at pH ≥ 8; the book gives nothing in between. */
export function litmusOf(pH: number): LitmusColour {
  if (pH <= LITMUS.red_max + 1e-9) return 'red';
  if (pH >= LITMUS.blue_min - 1e-9) return 'blue';
  if (Math.abs(pH - LITMUS.violet) <= 1e-9) return 'violet';
  return 'between';
}

export type PhenolColour = 'colourless' | 'pink' | 'edge';

/** Bảng 2.1: colourless at pH < 8, pink at pH > 8; at exactly 8 the book names no colour. */
export function phenolphthaleinOf(pH: number): PhenolColour {
  if (pH < PHENOLPHTHALEIN.colourless_below - 1e-9) return 'colourless';
  if (pH > PHENOLPHTHALEIN.pink_above + 1e-9) return 'pink';
  return 'edge';
}

/** pH-paper colour at a pH (nearest whole pH of the printed 1–14 scale). */
export function paperColourOf(pH: number): string {
  const i = Math.min(14, Math.max(1, Math.round(pH))) - 1;
  return PH_PAPER[i] ?? PH_PAPER[0] ?? 'transparent';
}

export type Solute = 'HCl' | 'NaOH';

/**
 * A strong acid or strong base of concentration c (mol/L), fully dissociated (tr. 18–19), at
 * 25 °C. The water's own ions are kept: [H⁺] is the positive root of the charge balance
 * h² ∓ c·h − Kw = 0, so very dilute solutions tend to pH 7 instead of crossing it.
 */
export function strongSolutionH(solute: Solute, c: number): number {
  const root = Math.sqrt(c * c + 4 * KW);
  return solute === 'HCl' ? (c + root) / 2 : (2 * KW) / (c + root);
}

/**
 * Independent check of `strongSolutionH`: bisection on lg[H⁺] of the charge balance
 * [H⁺] + [Na⁺] = [OH⁻] + [Cl⁻] (no closed form used).
 */
export function bisectedH(solute: Solute, c: number): number {
  const na = solute === 'NaOH' ? c : 0;
  const cl = solute === 'HCl' ? c : 0;
  const f = (lg: number) => {
    const h = 10 ** lg;
    return h + na - KW / h - cl;
  };
  let lo = -16;
  let hi = 2;
  for (let i = 0; i < 200; i++) {
    const mid = 0.5 * (lo + hi);
    if (f(mid) > 0) hi = mid;
    else lo = mid;
  }
  return 10 ** (0.5 * (lo + hi));
}
